versions.variantCss:
.wemd-code-block[data-variant="bytedance-code-dark"] {
  background: #1a1a1a;
  border-radius: var(--wemd-border-radius);
  padding: 16px 20px;
  margin: 16px 0;
  overflow-x: auto;
  border: 1px solid #2a2a2a;
}
.wemd-code-block[data-variant="bytedance-code-dark"] .wemd-component-body {
  padding: 0;
}
.wemd-code-block[data-variant="bytedance-code-dark"] .wemd-component-body .wemd-child-1 {
  color: var(--wemd-primary);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  margin: 0 0 8px 0;
}
.wemd-code-block[data-variant="bytedance-code-dark"] .wemd-component-body .wemd-child-2 {
  color: #e5e7eb;
  font-family: 'JetBrains Mono', 'SF Mono', Consolas, monospace;
  font-size: 13px;
  line-height: 1.7;
  margin: 0;
  white-space: pre;
}
